// A module groups related lessons. Each lesson contains teaching pages, questions,
// and its assessed training. Practical assessments only use simulated capabilities.
export const modules=[
 {id:'aboard',title:'Before you leave',outcome:'Use boat terminology, identify essential equipment, and prepare a safe crew briefing.'},
 {id:'wind',title:'Your first sail',outcome:'Read the wind, raise sails, get underway, and hold a steady course.'},
 {id:'trim',title:'Make the wind work',outcome:'Recognize points of sail and connect sail angle with speed and heading.'},
 {id:'maneuvers',title:'Change direction',outcome:'Head up, bear away, tack, gybe, and recover from the no-go zone.'},
 {id:'conditions',title:'Stay in control',outcome:'Distinguish true and apparent wind, reduce sail, and make conservative weather decisions.'},
 {id:'navigation',title:'Find your way',outcome:'Interpret a practice chart, steer a bearing, monitor depth, and execute a short route.'},
 {id:'seamanship',title:'Share the water',outcome:'Maintain a lookout and reason through basic traffic and weather situations.'},
 {id:'harbor',title:'Arrive and depart',outcome:'Plan docking and anchoring, rehearse stopping, and prepare for departure.'},
 {id:'readiness',title:'Respond and review',outcome:'Explain emergency priorities and demonstrate a complete simulated sailing exercise.'},
];
const q=(prompt,options,correct,explanation)=>({prompt,options,correct,explanation});
const step=(label,kind,value,duration=0,hint='')=>({label,kind,value,duration,hint});
const lessons=[];
const GENERIC_TRANSFER='Practice this with a qualified instructor aboard a real yacht. The simulator cannot reproduce crew coordination, loads, or all vessel behavior.';
function lesson(module,title,concepts,observe,mistake,quiz,practice=null,transfer=GENERIC_TRANSFER){
 const index=lessons.length;
 lessons.push({id:`sail-${String(index+1).padStart(2,'0')}`,module,title,sub:modules.find(m=>m.id===module).outcome,
  concepts,observe,mistake,quiz,practice,transfer,genericTransfer:transfer===GENERIC_TRANSFER,minutes:practice?10:6,prerequisite:index?lessons[index-1].id:null,
  type:practice?'Guided practice':'Theory & decisions',body:concepts[0],goal:practice?practice.steps[0].label:'Read the briefing and check your understanding',tip:observe[0]});
}
lesson('aboard','Safety before speed',[
 'A good departure starts with the crew, the weather and the boat, not the engine. Everyone wears a lifejacket that fits, knows where the emergency gear is, and knows how you will call for help and get a person back out of the water.',
 'Before you leave, brief the crew and check the boat:\n• Crew: the boom, which swings across when the boat turns and can knock a person overboard; things to trip on; where to hold on; and keeping hands clear of loaded lines and winches.\n• Boat and plan: the forecast, local restrictions, radio and phone, fuel or battery charge, and that the boat is seaworthy (sound and fit for the trip).',
 'Choose conditions that suit the least experienced person aboard, and agree in advance when you will turn back. This course builds understanding and some simulated skills; finishing it does not qualify you to skipper a real yacht.',
 'Before a trip of several days, give the crew a fuller briefing:\n• Going overboard: why it is dangerous and how to stay aboard.\n• Jobs: what help you will need from each person. Ask them to tell you about anything that seems unusual.\n• Fire: care with the stove and anything else that can burn.\n• Leaving the boat: what to do if you must abandon it.\n• Fragile equipment: how to use the toilet and other gear that is easy to damage.'
],['Before departure, tell your crew where to sit, how to move, and who will keep lookout.','Identify the boom and imagine its sweep across the cockpit.'], 'Starting because the weather looks pleasant without checking the forecast or briefing the crew.',[
 q('A new crew member is aboard. What comes before departure?',['Demonstrate maximum speed','Fit lifejackets and explain hazards, emergency equipment, and roles','Leave first and explain the controls underway'],1,'Prepare the crew and boat before getting underway; discovering a missing safety item after departure is too late.'),
 q('What does passing this simulator course establish?',['Permission to charter any yacht','Understanding and selected skills in a simplified simulation','Readiness to sail alone in all weather'],1,'On-water instruction and assessment are still needed. The simulator omits many physical and environmental demands.')]);
lesson('aboard','Know your yacht',[
 'Bow means the front; stern means the back. Port is the left side and starboard the right when facing the bow. These names stay with the boat however you face, so “rock to port” means the same side to everyone aboard.',
 'The mainsail is behind the mast; the headsail is forward. The boom is the pole along the mainsail’s foot (bottom edge). The keel, the heavy fin underneath, helps keep the boat upright and resists the wind pushing it sideways; the rudder steers when water flows over it.',
 'Use Chase for the whole boat, Helm for the sailing viewpoint, and Cockpit to inspect the wheel, winches, and screens.'
],['Switch to Cockpit and locate the wheel, the companionway (the steps down into the cabin), and the winches for pulling ropes.','Switch to Chase and identify the bow, mast, boom, and two sails.'], 'Calling a side port or starboard from whichever direction you happen to be looking.',[
 q('You are facing the stern. Which side is port?',['Your current left','Your current right','Whichever side the wind comes from'],1,'Port is the yacht’s left when facing forward, so it is on your right when facing aft.'),
 q('What needs water flowing over it to steer effectively?',['The anchor','The mast','The rudder'],2,'The rudder changes the direction of water flow. With little boat speed its authority is reduced.')]);
lesson('aboard','Lines, winches, and loads',[
 'A halyard raises a sail, and a sheet sets the sail\'s angle to the wind. A reef reduces the sail area you show. A cleat (a horn-shaped fitting) or a clutch (a lever lock) holds a line. A winch (a drum turned with a handle) takes the load, because a loaded sheet pulls harder than hands can hold.',
 'On this yacht, the colored sheets run aft (toward the back) to the cockpit winches. Look at the wraps and clutches in Cockpit view. The Boat systems panel sets each of the two halyards and sheets separately, along with other controls explained on the next pages. In the app, the sliders set the controls; they do not show how you handle a real line.',
 'The hoist controls set how far the mainsail and the headsail (the front sail) are raised. Each sheet sets one sail\'s angle, separately from the other. Three more controls shape the mainsail. The traveler slides the mainsheet\'s lower end across the boat. The vang pulls the boom (the pole under the sail) down, so the sail\'s top does not twist open. The outhaul stretches the bottom edge, which flattens the sail. Change one control at a time to see what each does.',
 'The reef control makes the mainsail smaller, and the engine control sets reverse, neutral or ahead. Return to neutral before a sailing test, so only the sails drive the boat. The anchor rode (the rope or chain to the anchor) slider sets a target. The windlass (the motor winch at the front) lets the rode out or pulls it in over time; watch how much is actually out, and stop it when needed.',
 'Keep fingers, loose clothing and hair away from loaded lines, because they can be pulled into a winch. Learn real winch work, line handling and knots with an instructor, including how to ease a loaded line under control. In the app, a mouse cannot teach you the feel of a loaded line.',
 'The vang, or kicking strap, keeps the boom down so the top of the sail keeps its power. On a reach (wind from the side) or a run (wind from behind), the mainsheet pulls the boom out more than down. Without the vang, the boom rises and the top of the sail twists open and loses power. In a strong gust, easing the vang lets the top of the sail spill wind.'
],['Follow a colored sheet from the deck to its winch.','Compare a halyard\'s job (lifting the sail) with a sheet\'s job (setting its angle).'], 'Treating a heavily loaded sheet like a slack rope, or mixing up the sheet and the halyard.',[
 q('You want to change the mainsail\'s angle. Which line does that?',['Mainsheet','Main halyard','Anchor rode'],0,'The mainsheet controls the boom and so the mainsail\'s angle; the halyard raises the sail.'),
 q('Can the app\'s winch model teach you to handle a loaded rope safely?',['Yes, fully','Only at maximum zoom','No; handling real lines needs supervised practice'],2,'The drawn hardware shows you where things are. It does not simulate hand position, friction or line loads.')]);
lesson('aboard','Read the instruments',[
 'Heading is the direction the bow points, measured clockwise from north: 000° north, 090° east, 180° south, 270° west. Speed is shown in knots; one knot is one nautical mile per hour.',
 'The multifunction display behind the wheel and the dashboard below the controls show the same live readings. Wind over water is the wind measured against the water rather than the land (Lesson {lesson:sail-05} explains it); its angle is measured from the bow. Depth estimates water depth, not clearance below the keel: subtract the keel’s depth, or you can run aground in water that looks deep enough.',
 'Current and leeway (sideways slip from the wind) can push you off your heading. Course and speed over ground, from GPS, are your real track and speed over the seabed. Compare them with heading and speed through water on the dashboard. You can enlarge the display for easier reading.',
 'The app combines a compass and a wind indicator in one dial. North stays at the top, east at the right, south at the bottom, and west at the left, even when the boat or camera turns. Read the white boat symbol’s bow against the compass scale to find your heading.',
 'The gold arrow identifies where wind over water comes from. The shaded no-go sector surrounds that source; it marks headings too close to the wind for sailing (explained in Lesson {lesson:sail-05}). In this example, the white boat points northeast at 045°, while the arrow and sector face northwest at 315°. The knots reading beneath the dial is wind speed.'
],['Open Helm or Cockpit and compare the multifunction display behind the wheel with the dashboard below the controls.','Select Chart and find the yacht symbol and north arrow.','Find the floating compass. Identify north, read the white boat’s heading, then read the gold wind-from arrow. These are two separate bearings.'], 'Reading depth as guaranteed clearance or treating heading as a guaranteed ground track.',[
 q('Which heading points east?',['000°','090°','270°'],1,'Bearings are measured clockwise from north; east is 090°.'),
 q('At 6 knots, how far would you travel in 30 minutes without current?',['6 nautical miles','12 nautical miles','3 nautical miles'],2,'Distance = speed × time. Six nautical miles per hour for half an hour is three nautical miles.'),
 q('On the illustrated app compass, the white bow points to 045° and the gold arrow to 315°. What is your heading?',['045° — read the white bow','315° — read the gold arrow','135° — follow the airflow'],0,'Heading comes from the white boat’s bow: 045°. The gold arrow gives the wind-from bearing, 315°. Neither the wind pointer nor the shaded sector is a course to follow.')],{setup:{sails:0},steps:[step('Inspect the cockpit instruments','camera','deck'),step('Open the navigation chart','event','chart')],debrief:'You can now locate the displays. Check instruments regularly while maintaining an outside lookout.'});
lesson('wind','Where the wind comes from',[
 'Wind is named for where it comes from. A northwesterly wind comes from the northwest (315°) and blows toward the southeast (135°). Windward is the side the wind comes from; leeward is the side it blows toward. Sailors name the source because that is where the wind’s force, the waves and any approaching weather come from.',
 'A sail is a flexible wing: it only works when air flows across it at an angle. Point the bow straight into the wind and the sail lines up with the airflow and just flaps like a flag, so it makes no driving force. The no-go zone is the range of headings too close to the wind for the sail to work: about 40–45° on either side for most cruising yachts (on a clock face, from 12 round to between the 1 and the 2), and 38° in this simulator. To reach a place upwind, you sail a zigzag outside it.',
 'The wind you sail by is the wind over the water. If the water itself is moving (a current), that wind differs from the forecast, which gives the wind over a fixed point: a current flowing with the wind makes the wind you feel weaker. Once the boat moves, it also feels its own airflow, called apparent wind (Lesson {lesson:sail-17}). With no current, the forecast wind is the one that matters.',
 'The app’s compass shows the wind like a weather vane: the gold arrowhead points to where the wind comes from. The shaded no-go sector sits around it. Diagrams of moving air point the other way, toward where the air goes. In the example, wind from 315° and a heading of 045° are 90° apart: a beam reach, with the wind straight across the side (Lesson {lesson:sail-09}). When the boat turns, only the white boat symbol moves; the gold arrow and the sector stay where the wind is.'
],['With no current and wind from 315°, compare headings 315°, 045°, and 135° on the compass.','The 045° heading puts the wind approximately across the side.','On the app compass, compare the white bow with the shaded sector. Say where the wind comes from and where the air moves before choosing a heading.'], 'Interpreting the arrow as where the wind is going rather than where it comes from.',[
 q('A wind from 315° comes from which direction?',['Southeast','Northwest','Northeast'],1,'315° is northwest. Wind direction is conventionally named for its source.'),
 q('Why can a yacht not sail straight into the wind?',['The compass stops working','The keel becomes too heavy','The sail lines up with the airflow and just flaps, so it makes no driving force'],2,'A sail needs air flowing across it at an angle. Outside the no-go zone it works like a wing; to go upwind you zigzag by tacking, turning the bow through the wind from one zigzag to the next.'),
 q('Why do the app’s gold arrow and shaded no-go sector both face 315° in this example?',['They tell you to steer toward 315°','The air is moving toward 315°','Both identify the wind’s source; the air moves toward 135°'],2,'The pointer marks wind from 315°, and the sector marks headings too close to that source. Air flows toward 135°. The white boat at 045° is outside the sector, on a beam reach.')]);
lesson('wind','Raise the sails',[
 'Hoist the mainsail with the bow pointing into the wind. The sail then lines up with the airflow and flaps with almost no load (it luffs), so it slides up easily and the boom cannot swing hard. With the sheet eased, the sail cannot fill by surprise.',
 'Before hoisting, check the lines, the space and the crew. Halyards and sheets must be clear and not twisted, because a twisted line jams the sail half-way up. Make sure you have room to drift while you work. Keep the crew clear of the boom, which can swing. The mainsail usually goes up first: it sits at the back of the boat, so like the tail of a weather vane it helps hold the bow toward the wind while you work. The headsail follows. In the app, Raise sails hoists both at once; Boat systems hoists each one separately.',
 'A raised sail facing the wind still makes no drive. To get moving, bear away (turn the bow away from the wind) until the wind is well to one side, then sheet in (pull the sheets in) until the sails stop flapping. Only then do they work as wings.',
 'Sails are also your backup engine, so keep one ready to set when motoring near a harbor. If the engine stops between the breakwaters (the harbor walls), unroll or hoist a sail at once so the boat keeps drive and steering and you can sail clear. Anchoring in the entrance blocks it, and the anchor may not hold before the boat reaches the rocks.'
],['Start the exercise facing into the wind with sails lowered.','Raise the sails; then turn to a sailable course in later exercises.'], 'Assuming raised sails always propel the boat, or hoisting without first checking the lines and boom area.',[
 q('Before a real mainsail hoist, what should be checked?',['Only the chart color','Clear lines, sea room, crew, and an unloaded sail','Whether the boat is at top speed'],1,'Preparation prevents jams and unexpected sail loading.'),
 q('Why is the mainsail hoisted with the bow pointing into the wind?',['The sail flaps with almost no load, so it goes up easily and the boom stays quiet','It makes the boat go fastest','The compass needs it'],0,'Pointing into the wind, the sail lines up with the airflow and carries little load. Across the wind it would fill, pull hard and swing the boom while you are still hoisting.')],{setup:{heading:315,sails:0},steps:[step('Raise the sails','sails',1,2)],debrief:'You set the sails in the model. The next exercise starts on a reach where they can produce drive.'});
lesson('wind','Feel the boat accelerate',[
 'A beam reach puts the wind at about 90° to the boat. It is the easiest point of sail to start on: you are far from the no-go zone, and the sail can be set at a clear angle to the wind, so it makes plenty of forward drive.',
 'A yacht weighs several tonnes, so it speeds up slowly. Water drag also grows quickly with speed. The boat accelerates until the push from the sails equals the drag from the water, then settles at a steady speed. Change the wind or the trim and it finds a new balance, again gradually.',
 'The rudder is a small underwater wing that only steers when water flows past it. So it does little at rest and grips better as speed builds; use small helm movements. Which way the bow turns:\n• Wheel: steers like a car; turn it to port and the bow goes to port.\n• Tiller: works the opposite way; push it to starboard to turn the bow to port.\n• Going backward: water reaches the rudder from behind, so the same helm turns the bow the other way.',
 'Waves change how well the rudder grips, too: steering works best when the boat heads into them. Then water flows quickly past the rudder and the bow meets each wave. Running with the waves, especially fast, each wave lifts the stern and the flow past the rudder drops, so the boat can swing off course. Steer actively, and slow down if the course becomes hard to hold.'
],['Begin on 045° with a northwesterly wind, sails lowered, and anchor up.','Raise both sails, then watch speed increase. Keep the helm centered while the yacht builds enough speed to steer.'], 'Applying full helm while stationary and expecting the yacht to pivot instantly.',[
 q('When does this rudder gain steering authority?',['As water flow and boat speed increase','When the anchor is lowered','Only when sails are lowered'],0,'A yacht normally needs water flow over the rudder to respond.'),
 q('After centering the helm, what happens?',['The yacht returns automatically to north','The turn reduces and the yacht tends to maintain its new heading','The yacht stops instantly'],1,'The helm controls turning, not a selected compass heading.')],{setup:{heading:45,sails:0,trim:65,jibSheet:60},steps:[step('Raise sails and build speed above 3 knots','speedAbove',3,6)],debrief:'The sail force accelerated the boat; the rudder became useful as speed built.'});
lesson('wind','Hold a steady course',[
 'Steer by something far away, such as a headland or a cloud, and use the compass to check it. A distant mark shows a turn at once; the compass number lags behind and swings in waves.',
 'A turning boat keeps turning after you center the helm, because it carries turning momentum, like a revolving door. So center the helm before you reach the new heading and let the boat glide onto it. If you wait until you are on the heading, you overshoot, correct back and zigzag. Small, early corrections give a straight track.',
 'If you keep needing helm just to hold a straight course, the boat is telling you something. A yacht that keeps trying to turn toward the wind (weather helm) usually has too much sail up or is heeling too far; easing the mainsheet (letting it out) or reefing (making the sail smaller) fixes it (Lesson {lesson:sail-18}). Keep a lookout too, because a well-steered course can still lead into danger.'
],['Use short port or starboard inputs, then select Center.','Watch heading settle rather than keeping the helm over.'], 'Holding a large correction too long and oscillating from one side of the target to the other.',[
 q('You are approaching your intended heading. What usually helps avoid overshoot?',['Center the helm in good time','Increase helm to maximum','Lower the anchor'],0,'The boat keeps turning for a moment, like a revolving door, so reducing the correction early helps the turn settle.'),
 q('Which is a complete steering routine?',['Watch the compass only','Look away until the boat drifts','Look out, check heading, make a small correction, reassess'],2,'Steering and lookout must happen together.')],{setup:{heading:60,speed:3,trim:34},steps:[step('Hold 045° ±5°, above 2 knots, for 10 seconds','heading',45,10,'Port brings 060° down toward 045°. Center before you reach the target.')],debrief:'A steady course requires small corrections and anticipation, not continuous large helm input.'});
lesson('trim','Find a beam reach',[
 'A point of sail is the angle between the bow and the wind, not a compass heading. Moving away from the wind:\n• Close hauled: about 40–50° off the wind, sails pulled in tight.\n• Close reach: about 60°.\n• Beam reach: 90°, wind straight across the side.\n• Broad reach: about 135°, wind from behind the side.\n• Run: about 180°, wind from straight behind.',
 'Each point of sail has its own sail setting. A rough guide is that the sail sits at about half the wind angle: close hauled the boom is near the centerline, on a beam reach it is about halfway out, and on a run it is far out. You can be on any point of sail with the wind on either side: with wind from 315°, both 045° and 225° are beam reaches, one with the wind on the port side and one on starboard.',
 'As the boat speeds up, the wind it feels swings forward, because its own motion adds a breeze from ahead (Lesson {lesson:sail-17} explains this). So trim in a little as you accelerate. If the wind shifts, your point of sail changes even when your heading does not.',
 'Running before the wind, or simply running, means sailing with the wind and the waves coming from behind. It feels calm because the apparent wind is small and the boat barely heels. But the waves lift the stern, and the risk of an accidental gybe, the boom swinging across without warning, is highest.'
],['Compare the bow marker with the direction of wind over water on the onboard display.','Notice that two different compass headings can give the same point of sail.'], 'Memorizing a compass heading as a point of sail when the wind direction may change.',[
 q('What defines a beam reach?',['Heading east','Wind about 90° off the bow','Sails completely lowered'],1,'Points of sail are relative to the wind.'),
 q('If the wind shifts, can an unchanged heading produce a different point of sail?',['Yes','No','Only at anchor'],0,'A wind shift changes the angle between the bow and the wind.')],{setup:{heading:75,speed:3,trim:40},steps:[step('Hold a beam reach above 2 knots for 8 seconds','windAngle',[80,105],8)],debrief:'You selected a course using the wind relationship, rather than the compass alone.'});
lesson('trim','Sail close hauled',[
 'How can a boat sail toward the wind? Air flowing around the curved sail makes a force, like the lift on an aircraft wing. Close hauled, that force points mostly sideways and only a little forward. The keel grips the water and resists the sideways part, so what is left drives the boat forward. That is why close hauled feels heeled (leaning over) and slower than a reach, and why the boat slides sideways a little (leeway).',
 'Pointing as close to the wind as you can is not always fastest upwind. Steer too close to the wind (pinching) and the front of the sail starts to flap, drive drops and the boat slows; a slower keel grips less, so the boat also slips sideways more. A few degrees lower with good speed usually gets you upwind sooner. As you head up (turn toward the wind), trim in; if speed fades, bear away (turn away from it) a little.',
 'Telltales are short ribbons on both sides of the sail near its front edge. When both stream straight back, the air is flowing well. If one misbehaves:\n• Windward one (on the side the wind comes from) lifts or spins: you are too close to the wind or the sail is too far out. Bear away a little or trim in.\n• Leeward one droops or spins: the sail is pulled in too far. Ease it or head up a little.'
],['Start on a reach and steer nearer to the wind.','Trim inward as the wind angle decreases.'], 'Pinching: pointing too close to the wind and losing the speed that makes the boat and rudder work.',[
 q('What is pinching?',['Sailing too close to the wind and losing useful drive','Sailing with too much anchor chain','Turning away from the wind'],0,'A slightly lower course may produce better upwind progress because it preserves speed.'),
 q('Relative to a beam reach, a close-hauled mainsail is generally…',['Further out','Lowered completely','Trimmed closer to the centerline'],2,'As you sail closer to the wind, the sail angle normally comes inward.')],{setup:{heading:30,speed:3,trim:20},steps:[step('Hold 45°–58° off the wind above 2 knots','windAngle',[45,58],8)],debrief:'You balanced pointing with boat speed. The simulator estimates leeway but does not assess reading physical telltales.'});
lesson('trim','Bear away to a broad reach',[
 'Bearing away turns the bow away from the wind and makes the wind angle larger. Ease the sheets as you turn, so each sail keeps its angle to the wind. If you leave them tight, the sail stalls: it heels the boat and pushes it sideways without making much speed.',
 'As you turn downwind, the sail works less like a wing and more like a parachute: the wind mostly pushes on it from behind. The sideways force fades, so the boat heels less and feels calmer. On a broad reach, with the wind from behind the side, many boats are fast and comfortable.',
 'Near dead downwind, watch the boom, because it can suddenly swing across. If the wind comes round to the boom’s side (sailing by the lee), it can cause an accidental gybe: the stern swings through the wind and the boom slams across, hitting heads and breaking gear. While learning, keep the wind over the back corner, about 150° off the wind or less, and know which side the boom would swing to.',
 'When someone must work on the foredeck (the deck at the front) in strong wind and big waves, bear away to a broad reach. The boat heels less, the bow slams less and the apparent wind drops because you are moving with the wind, while you stay clear of the dead run where an accidental gybe is likely. Hold a steady course until the crew is back.'
],['Increase your angle to the wind, then ease the sheet.','Keep a margin from dead downwind while learning.'], 'Leaving the mainsheet tight after bearing away or losing track of which side the boom will move to.',[
 q('What happens to wind angle when you bear away?',['It always becomes zero','It increases','It becomes a compass heading'],1,'The bow moves farther away from the source of the wind.'),
 q('What maneuver becomes a concern near dead downwind?',['An unintended gybe','An automatic tack','Instant anchoring'],0,'A small heading or wind change can take the wind across the stern and move the boom.')],{setup:{heading:55,speed:3,trim:50},steps:[step('Hold a broad reach, 120°–150° off the wind','windAngle',[120,150],8)],debrief:'You increased the wind angle and kept clear of an accidental stern crossing.'});
lesson('trim','Trim with feedback',[
 'Trim means setting the sail at the right angle to the wind. Too far out and the front edge flaps (luffing): air is not flowing across the sail properly, so it makes little drive. Too far in and the air breaks away from the back of the sail (stalling), like a wing tipped too steeply: the boat heels and slows but does not speed up. The best setting is just inside the point where luffing starts.',
 'The classic method: ease the sheet slowly until the front of the sail starts to flap, then pull it in just until the flapping stops. Telltales make this easier to see. Repeat it after every course change or wind shift. “When in doubt, let it out”: a slightly eased sail costs little speed; an over-tight one costs a lot.',
 'Change one thing at a time and give the boat time. Speed changes slowly (Lesson {lesson:sail-07}), so wait several seconds to see whether a change helped. In this app, the “Suggested” value under the Mainsheet slider, worked out from the apparent wind (the wind the moving boat feels), lets you check your result; on a real boat you trim by watching the sail’s front edge and the telltales.'
],['Leave the helm centered and change only the sheet.','Wait for speed to respond instead of making constant large changes.'], 'Changing heading and sheet simultaneously so you cannot tell which adjustment improved the boat.',[
 q('For a useful trim comparison, which technique helps?',['Change all controls rapidly','Hold a steady course and adjust one thing at a time','Anchor while trimming'],1,'A stable course makes the effects of sheet changes easier to observe.'),
 q('Both telltales are streaming. You pull the sheet in further and the leeward telltale starts to spin. What happened?',['The sail is now luffing','The wind dropped to zero','The sail is pulled in too far and starting to stall'],2,'Pulling in too far makes the airflow break away on the back (leeward) side. Ease the sheet until the leeward telltale streams again.')],{setup:{heading:45,speed:3,trim:80},steps:[step('Hold efficient trim and speed for 10 seconds','trim',6,10)],debrief:'You used a controlled adjustment and allowed time for the speed response.'});
lesson('maneuvers','Head up and bear away',[
 'Heading up means turning toward the wind; bearing away means turning away from it. Port (left) and starboard (right) only say which way the boat turns. "Turn left" tells you nothing about the wind, so you must know which side the wind is on.',
 'Whether a left turn heads up depends on your tack (which side the wind comes over). With the wind from the north, heading east, turning left heads up; heading west, the same left turn bears away. So check the wind first, then trim to match: head up and pull the sheets (the sail ropes) in; bear away and let them out.',
 'Practice both turns: sail first at 50° off the wind, then at 110°. At 110° the wind is a little behind the beam (straight out to the side). Let each course settle before the next change, so you can see what the turn did.'
],['Notice whether the wind angle grows or shrinks with each helm input.','Center the helm at each target, and adjust trim to the new point of sail.'], 'Assuming "turn left" always means "head up."',[
 q('Is a port (left) turn always a turn toward the wind?',['Yes','No; it depends on the tack and wind direction','Only above 5 knots'],1,'The same helm movement changes your angle to the wind in opposite ways on opposite tacks.'),
 q('What should you do after a big course change?',['Check sail trim and lookout again','Ignore the sails','Always drop anchor'],0,'The new heading changes the airflow on the sails and what is around the boat.')],{setup:{heading:45,speed:3,trim:30},steps:[step('Settle at 45°–55° off the wind','windAngle',[45,55],6),step('Bear away and settle at 105°–115°','windAngle',[105,115],6)],debrief:'You changed your relationship to the wind in both directions and stabilized between turns.'});
lesson('maneuvers','Make a controlled tack',[
 'A tack turns the bow through the wind, so the wind moves to the other side of the boat and the sails swap sides. From close hauled to close hauled, it is a turn of about 90°. Before you start, look for traffic, check sea room (open water with no boats or shore to hit while you turn) and warn the crew with “Ready about”.',
 'Speed is what gets you through. Inside the no-go zone the sails flap and make no drive, so only the boat’s momentum carries the bow across. Start with good speed and turn steadily. Too slow, and the boat stops head to wind (in irons, Lesson {lesson:sail-16}). Too sharp, and the rudder, turned hard over, acts as a brake.',
 'On a real yacht, each step of the tack has its own moment:\n• Put the helm over and call the turn, for example “Lee-ho”, meaning the turn starts now.\n• As the headsail starts to flap, release its old sheet.\n• As the bow passes the wind, pull in the new sheet on the other side.\n• Center the helm on the new close-hauled course and retrim.\nExpect to lose some speed, and rebuild it before pointing high. In the app the sails swap sides automatically.'
],['Start with wind over the starboard side, then turn to starboard so the bow swings past 315°, where the wind comes from.','Continue past the no-go zone, center the helm, and rebuild speed.'], 'Stopping the turn in the no-go zone, or calling a turn across the stern a tack.',[
 q('Which part of the yacht crosses the wind during a tack?',['The stern','The anchor','The bow'],2,'A tack takes the bow through the source of the wind; a gybe takes the stern through it.'),
 q('Before the turn, what is needed?',['Lookout, sea room, preparation, and enough boat speed','An anchor already lowered','All crew standing beneath the boom'],0,'Preparation and momentum help the boat complete the no-go-zone crossing.')],{setup:{heading:265,speed:4,trim:14},steps:[step('Turn the bow through the wind and recover above 2 knots','tack',null,6,'Turn starboard through 315°, then continue to about 005° and center. Trim for the new course.')],debrief:'The assessment recorded a bow crossing, a new tack, and recovered speed. Sheet transfer remains an on-water skill.'});
lesson('maneuvers','Make a planned gybe',[
 'A gybe turns the stern through the wind. It is more dangerous than a tack because the sails stay full the whole time. In a tack the sails go slack as the bow passes the wind; in a gybe the wind gets behind the mainsail and throws the boom across the cockpit with force.',
 'So you control the boom and warn the crew (“Stand by to gybe”) to keep heads clear. Before the stern crosses the wind, pull the mainsheet in so the boom is near the center and has only a short distance to swing. Turn slowly. As the boom crosses, ease the sheet out smoothly on the new side. Then steady the helm, because the boat tends to swing up into the wind.',
 'Make it a small, deliberate turn from a broad reach on one side to a broad reach on the other. An accidental gybe is the dangerous version because nobody is ready. It usually comes from sailing by the lee (the wind coming over the same side the boom is on), when the boom can flip across without warning. In the app the boom is animated, but its impact force is not modeled.',
 'In strong wind a gybe can break gear or injure the crew. If you need to turn from one broad reach to the other, consider going the long way round: head up, tack through the wind, then bear away on the new side. It takes longer, but the boom never swings across with full force.'
],['Start at 160° with wind from 315°, so the wind is behind you on a broad reach. Turn port toward and through 135°.','Settle near 110° and keep the wind well aft of the beam.'], 'Treating a gybe like an unannounced sharp turn with the mainsheet fully loose.',[
 q('What is the principal gybe hazard for the crew?',['A compass reversal','The boom and mainsheet crossing the cockpit','The anchor becoming heavier'],1,'Control the boom and keep people clear of its path.'),
 q('What distinguishes a gybe from a tack?',['The stern passes through the wind','The boat must use an engine','The sails are always lowered'],0,'The wind crosses the stern during a gybe and the bow during a tack.')],{setup:{heading:160,speed:3.5,trim:78},steps:[step('Cross the wind with the stern and settle on the new tack','gybe',null,6,'Turn port through 135° and settle near 110°. Center the helm.')],debrief:'You made the correct stern crossing. Real mainsheet control must be learned with supervision.'});
lesson('maneuvers','Recover from loss of drive',[
 'In irons means stopped, or nearly stopped, pointing into the wind. The sails flap, so there is no drive, and as speed falls the rudder loses its grip on the water.',
 'Avoid it by keeping speed through a tack and not pinching (steering so close to the wind that the sails lose power). If you notice it early, use the speed you still have: bear away promptly until the sails fill, then trim to rebuild drive.',
 'A fully stopped boat needs another way to turn. On a real yacht the crew can hold the headsail out on one side (backing it) so the wind pushes the bow away, or let the boat drift backward and steer it round, remembering that steering works the opposite way going backward. Some crews use the engine. Backing sails is not modeled here, so this exercise starts with some speed left: use it before it runs out.'
],['Use the speed you still have to turn away from 315°, the direction the wind comes from.','Do not wait until speed reaches zero before correcting.'], 'Expecting the rudder to rotate a fully stationary yacht without water flow.',[
 q('Why should you act before all speed is lost?',['Residual water flow gives steering authority','The chart will disappear','The sails become too short'],0,'Water still flowing past the rudder lets you steer, so use it to get outside the no-go zone.'),
 q('The boat has stopped head to wind and starts to drift backward. What happens to the steering?',['It stops working completely','It works the opposite way: the same helm turns the bow the other way','It works exactly as when moving forward'],1,'Moving backward, water reaches the rudder from behind, so its effect reverses. Crews use this, together with a backed headsail, to turn the bow out of the no-go zone.')],{setup:{heading:325,speed:2.6,trim:20},steps:[step('Exit the no-go zone and rebuild speed above 2 knots','recover',null,7,'Turn starboard toward 010° or beyond before the remaining way disappears.')],debrief:'You used residual momentum. A stopped-boat recovery is a separate practical skill.'});
lesson('conditions','True and apparent wind',[
 'On a moving boat you feel the apparent wind, like the headwind you feel cycling in still air. It is the true wind plus the breeze of your own motion. True wind is what you would feel standing still. Instruments measure it over the ground or over the water (these differ in a current), so check which yours shows.',
 'As the boat speeds up on a reach (wind from the side), the apparent wind usually moves forward, toward the bow (the front). That is because your own breeze comes from straight ahead. Sailing downwind, you move with the air, so the apparent wind can get weaker. With no wind over the water, there is no wind direction, but a moving yacht still feels the breeze of its own motion.',
 'Name your course from the wind over water, but trim the sails to the apparent wind. In the app, compare Wind over water with Apparent wind on the onboard display. The point of sail (your angle to the wind) and the no-go zone (too close to the wind to sail) come from the wind over water. Trim to the apparent wind, because that is the air the sails actually feel; telltales (ribbons on the sail) and sail shape always show it directly.',
 'A sail works like an aircraft wing: it bends the airflow and pushes the boat partly forward and partly sideways. The keel (the fin under the hull), centreboard or underwater foils (small wings) resist the sideways push, so the forward part drives the boat. On a reach, a well-trimmed sail can keep driving even above true-wind speed. The boat stops speeding up when the forward push equals the water\'s resistance.',
 'Some efficient racing boats can therefore sail faster than the true wind. Light hulls and efficient sails help. Hydrofoils can lift the hull clear of the water, which cuts resistance even more. All the energy still comes from the wind moving over the water. An ordinary cruising yacht may have too much resistance to beat the wind\'s speed.',
 'In this example the apparent wind is stronger than the true wind and comes from further ahead. Assume no current and no leeway (sideways slip). A racing boat goes north at 30 knots (about 55 km/h) while a 20-knot wind blows from the west, at a right angle to its path. The apparent wind is about 36 knots, coming from about 34° to port (left) of the bow. Side note: because the two speeds are at right angles, they combine as √(20² + 30²) ≈ 36.1 knots. If the boat instead sailed straight downwind at the wind\'s speed, it would feel no wind at all in this simple case.',
 'Try it in Challenges → Apparent Wind Lab: record the wind at three moments:\n• With the sails down.\n• On a beam reach (wind straight from the side).\n• On a broad reach (wind from behind the side).\nOn the beam reach, the apparent wind gets stronger and moves forward as speed builds; on the broad reach it gets weaker.'
],['Imagine riding a bicycle in still air: you feel wind from ahead.','Compare the apparent wind display as speed increases on a steady course.'], 'Assuming true and apparent wind have the same direction and speed while the yacht is moving.',[
 q('Which wind does a moving sail actually feel?',['Only the weather forecast wind','Apparent wind','A fixed compass wind'],1,'Sails work with the airflow as it meets the moving yacht.'),
 q('You speed up on a steady beam reach. What happens to the apparent wind?',['It moves forward and gets stronger','It moves aft and gets weaker','It does not change'],0,'The boat’s own motion adds a breeze from ahead. Combined with the true wind, the apparent wind swings toward the bow and strengthens, so you trim in a little.'),
 q('Why can an efficient racing boat sail faster than the true wind on a reach?',['Boat motion creates an unlimited energy supply','The sail\'s lift can still push forward harder than the water resists','Every sailboat automatically matches apparent wind speed'],1,'The sail feels the apparent wind, while the keel and other underwater parts resist the sideways push. If resistance is low enough, the forward push can stay bigger than resistance even above true-wind speed. The energy still comes from the wind over the water.'),
 q('With no current or leeway, a boat goes 30 knots at a right angle to a 20-knot true wind. What apparent wind speed does it feel?',['10 knots','50 knots','About 36.1 knots'],2,'Speeds at right angles combine as √(20² + 30²) ≈ 36.1 knots. You only add or subtract speeds directly when they point along the same line. The example assumes the boat already does 30 knots.')]);
lesson('conditions','Reef before you need to',[
 'A reef makes the mainsail smaller and lower, and it pays to do it early. Wind force grows with the square of wind speed: 20 knots pushes about four times as hard as 10 knots, not twice. So a moderate rise in wind makes a big rise in the force heeling the boat and loading the rig. A smaller, lower sail catches less of that force and holds it lower down, which means less heel.',
 'Too much heel does not make a boat faster. The hull slips sideways more, the rudder grips less, and the boat keeps trying to turn into the wind (weather helm). Signs that it is time to reef: heavy steering, the boat rounding up toward the wind in gusts, and water along the side deck. “Reef when you first think about it”: it is far easier before the wind builds than during it.',
 'There is no single wind speed for reefing: it depends on the boat, the crew, the gusts and the sea. Compare the heel and the helm before and after a reef on the same course. The app’s Reef control shortens the main in one step; on a real boat it means handling the halyard (the rope that raises and lowers the sail) and the reefing lines (which pull the lower part down) under load, with the crew working together.',
 'Which sail you shrink also changes the steering. Sails behind the boat’s pivot point (the spot the boat turns around), such as the mainsail, turn the bow toward the wind; the headsail, in front, turns it away. Lower the headsail and the boat heads up; sail on the headsail alone and it bears away. On a boat with two masts, such as a ketch, the aft sail, called the mizzen, adds weather helm: when the helm gets heavy or the wind rises, reduce or lower the mizzen first, then reef the main.',
 'In a storm, reduce sail but do not take it all down. A small, well-set sail keeps the boat moving and steering and steadies the roll; a boat with no sail at all lies across the waves and cannot be steered.'
],['Observe heel and speed in the exercise’s 22-knot breeze.','Select Reef, keep the boat on a reach, and compare its response.'], 'Waiting until the crew are overloaded or using a fixed wind threshold without considering the boat.',[
 q('What is a sound reason to reef early?',['Increasing difficulty keeping the yacht controlled','Wanting the largest possible heel','Every yacht always reefs at exactly 20 knots'],0,'Reefing is a control decision based on boat, crew, and conditions.'),
 q('The wind rises from 10 to 20 knots. Roughly how much harder does it push on the sails?',['Twice as hard','The same','About four times as hard'],2,'Wind force grows with the square of wind speed: 2 × 2 = 4. That is why reefing decisions come earlier than many beginners expect.')],{setup:{heading:45,speed:4,windSpeed:22,trim:34},steps:[step('Set a reef and maintain steerage for 10 seconds','reef',true,10)],debrief:'You reduced sail area and retained control. Real reefing needs a practiced crew procedure.'});
lesson('conditions','Reduce power deliberately',[
 'A sailing yacht has no brakes, so plan every stop early. When you take power out of the sails, the boat keeps moving on its momentum and slows only as water drag works on it. A heavy boat can glide a long way, so leave sea room.',
 'Ways to take power out, from quickest to most complete:\n• Ease the sheets until the sails flap, so they stop working as wings.\n• Head up toward the wind, which reduces the angle and the drive.\n• Lower the sails, which removes drive completely.\nAs the boat slows, the rudder grips less, so steering becomes slow and weak.',
 'In this exercise, lower the sails and wait until the speed is below 1 knot. Do not use the anchor as a brake: dropping it at speed can rip out the gear, damage the boat or snag the bottom.',
 'On a real yacht you can also heave to: set the sails to work against each other so the boat almost stops. Tack without releasing the headsail, so it stays held on the wrong (windward) side; this is the backed headsail. Then steer as if to head up (tiller pushed away from the wind) and ease the main. The backed headsail pushes the bow away from the wind while the main and rudder push it back. The boat lies about 60° off the true wind, between close hauled and a beam reach, and drifts slowly to leeward. Use it to rest, reef or wait in strong wind; the app does not model it.'
],['Compare the speed before and after lowering sails.','Notice the delay and the reduction in rudder authority.'], 'Dropping an anchor at speed as a routine way to stop.',[
 q('What remains after you lower the sails?',['Momentum','Full sail driving force','Guaranteed steering at zero speed'],0,'The boat continues to move until drag reduces its speed.'),
 q('Why leave room when slowing down?',['A yacht always reverses instantly','Stopping distance and declining steerage need to be anticipated','The compass becomes unreliable at low speed'],1,'Plan your speed reduction early enough to remain in control.')],{setup:{heading:45,speed:4,trim:34},steps:[step('Lower the sails','sails',0,1),step('Coast below 1 knot without anchoring','coast',1,3)],debrief:'You allowed momentum to decay instead of expecting an immediate stop.'});
lesson('conditions','Choose a weather limit',[
 'Read a marine forecast for the whole trip and some time beyond it, because a change can come earlier or later than forecast and trips often run long. Check three groups:\n• Wind: average strength, gusts and changes of direction.\n• Water: sea state (the size of the waves), tides and currents.\n• Other: visibility, temperature and local effects, such as a sea breeze or wind speeding up around a headland.',
 'Three situations make a moderate wind more dangerous than it sounds:\n• Wind against current: the current squeezes the waves together, so they get taller, steeper and closer, and can break.\n• A lee shore, a coast the wind blows toward: if the engine, a sail or the rudder fails, the wind pushes you onto it.\n• An offshore wind, blowing from the land: it feels calm near the coast, but the waves grow farther out and it can be hard to get back.',
 'Set your go/no-go limits before you leave: the conditions in which you will not go, or will turn back. Decide too what change would make you shorten the trip, and where you would go instead. The simulator’s wind is steady and its current does not change, so practice this judgment here as planning; real weather changes.',
 'When strong wind is forecast while you are in harbor, prepare the boat. Double the mooring lines and add fenders and chafe protection. Take the sails down and stow them below, or lash them tightly, and remove anything the wind can catch.',
 'Forecasts and the barometer tell you when to wait or turn back:\n• A low-pressure system moving toward your route brings strong wind and rising seas. Wait until it has passed rather than trying to beat it.\n• A falling barometer warns that the weather is getting worse.\n• If the forecast worsens soon after you leave, prepare for heavy weather with reefs, harnesses and jacklines, and turn back to the port you left rather than pressing on.\n• If you are already well along, choose a harbor ahead that is downwind and has a safe entrance in that wind.'
],['For a novice crew, decide what change would make you shorten or cancel a trip.','Name a sheltered alternative and a return deadline.'], 'Treating a low average wind speed as proof that the entire trip will be safe.',[
 q('The average wind is manageable but the forecast includes strong gusts and worsening visibility. What is appropriate?',['Ignore the gusts','Depart because only average speed matters','Reassess the trip against crew ability and safe alternatives'],2,'The entire forecast and its trend matter, not one number.'),
 q('Strong wind is forecast to blow onto the coast you plan to follow. Why is that a concern?',['It makes the compass inaccurate','It is a lee shore: if something fails, the wind pushes you toward land','It always makes the sea calmer'],1,'With wind blowing onto the shore you have little room to recover from a failure. Choose a route with more sea room or change the plan.')]);
lesson('navigation','Read a practice chart',[
 'A chart is a planning tool, not a picture to follow blindly. Before you use one, check its scale, which way is north, the depths, hazards and marks, and how up to date it is: an old chart can miss a new wreck or a buoy that has moved.',
 'Depths are numbers, usually in metres, and lines called contours join places of equal depth. Shallower water is usually shaded blue, areas that dry at low tide are green, and land is buff or yellow. Measure distance on the latitude scale at the side of the chart: one minute of latitude is one nautical mile.',
 'Buoys tell you where the safe water is and which side to pass. Lateral marks show the two sides of a channel, and each is passed on a set side; cardinal marks show on which side of a danger the safe water lies. Which color goes on which side depends on the region (IALA A or B), so check before you sail. In this app the amber buoys are only practice targets.',
 'In IALA Region A, red marks stay on your left and green marks on your right as you come in from sea.\n• Region A covers Europe, Africa, the Mediterranean and most of Asia and Australia.\n• Region B, where the colors are the other way round, covers most of the Americas, Japan, Korea and the Philippines.\n• Red port-hand marks are cans (flat-topped) and green starboard-hand marks are cones (pointed). Their lights flash in the same color.\nA harbor entrance follows the same rule, so a red and a green light close together at night often mark the entrance itself.',
 'Cardinal marks are named after the compass side of a danger where the safe water lies: pass north of a North mark, east of an East mark, and so on. Each carries two black cones on top, and the cones point to where the black is on the mark:\n• North: both point up; black over yellow.\n• South: both point down; yellow over black.\n• East: they point apart; black with a yellow band.\n• West: they point together; yellow with a black band.',
 'At night a cardinal mark shows a white quick-flashing light, timed like a clock face. North flashes without stopping; East gives three flashes, like 3 o’clock; South gives six and then one long flash, like 6 o’clock; West gives nine, like 9 o’clock. The long flash keeps a quick count of six from being mistaken for nine. Count a whole group before deciding which side to pass.'
],['Open the chart. Locate north, your position, and the next mark.','Identify land you must keep clear of along the intended route.'], 'Assuming a screen showing your position is a complete and current navigational chart.',[
 q('On a chart, what does one minute of latitude on the side scale measure?',['One kilometre','One nautical mile','One knot'],1,'Distance is measured on the latitude scale at the side of the chart, level with your position. The longitude scale along the top and bottom changes with latitude, so it is not used for distance.'),
 q('Which should a real chart check include?',['Only the screen brightness','Only the destination name','Scale, source, currency, depths, hazards, and local conventions'],2,'Charts need interpretation and context to support safe navigation.'),
 q('At night a mark shows nine quick white flashes, then darkness. Where is the safe water?',['To the west of the mark','To the east of the mark','All around the mark'],0,'Nine flashes, like 9 o’clock, mean a West cardinal mark: pass to the west of it.')]);
lesson('navigation','Steer toward a waypoint',[
 'A bearing is the direction from your position to a target, such as a waypoint (a planned point you steer for). Check that the direct track, the line you would travel over the ground, is safe and sailable.',
 'A direct bearing may point into the no-go zone (the arc near the wind where sails cannot drive) or cross land. Then plan a different route, such as tacking, rather than forcing the bow toward the target.',
 'Where the bow points is not always where the boat goes. Current and leeway (the wind pushing the boat sideways through the water) push you off course. Aim a little up-current of the mark so the drift carries you onto it, not past it. Check the bearing to the mark now and then: if it keeps changing while you hold your heading, you are being pushed off the line. In this exercise, pass within 35 metres of buoy 1.',
 'A course on the chart is measured from true north, but your compass does not point there. Two errors sit between them:\n• Variation: magnetic north is not at true north. The compass rose on the chart gives it for your area, for example 4° East.\n• Deviation: the boat’s own metal and electrics pull on the compass. It changes with the heading, so read it from the boat’s deviation card.\nGoing from compass to true, add errors to the East and subtract errors to the West: True = Compass + Deviation + Variation. Going from true to compass, do the opposite. A memory aid is CADET: Compass ADd East, True. Example: the chart course is 132° true and variation is 4° East, so the magnetic course is 128°. If you must steer 137° by compass to make it good, the deviation is 9° West.'
],['Open the chart before changing course.','Aim toward buoy 1, then check progress and depth regularly.'], 'Fixating on the target and ignoring land, traffic, or the wind angle.',[
 q('Your waypoint lies directly upwind. What is required?',['Plan a sailable route using tacks','Hold the bow in the no-go zone indefinitely','Increase the compass reading until the wind changes'],0,'You may need multiple legs to make progress toward an upwind destination.'),
 q('Is the direct bearing always a safe course?',['Yes','Only if the waypoint is visible','No; check hazards, depth, wind, and traffic'],2,'A bearing describes direction, not safety.'),
 q('The chart course is 100° true. Variation is 3° West and deviation on this heading is 2° East. What do you steer by compass?',['97°','101°','105°'],1,'True to magnetic: a West error is added, so 100° + 3° = 103° magnetic. Magnetic to compass: an East error is subtracted, so 103° − 2° = 101° compass. Check with CADET: 101° + 2° East − 3° West = 100° true.')],{setup:{x:20,z:5,heading:60,speed:3,trim:26},steps:[step('Open the chart to plan the approach','event','chart'),step('Reach buoy 1 with at least 3 m depth','waypoint',{x:90,z:-140,radius:35})],debrief:'You related chart position to the world and monitored a real approach in the simulation.'});
lesson('navigation','Estimate distance and time',[
 'For a first estimate, distance equals speed multiplied by time. At 4 knots, a 3-nautical-mile leg takes 3 ÷ 4 = 0.75 hour, or 45 minutes, if speed remains constant and there is no current.',
 'Dead reckoning advances an earlier position using course, speed, and time. Real estimates also account for current, leeway, and uncertainty; a fix (a position found from landmarks, bearings or GPS, not from your estimate) checks it.',
 'Record assumptions and update the estimate as conditions change. A precise-looking number is not an accurate prediction: an arrival time of 14:37 is still a guess if the current changes.',
 'Keep a logbook, and fill it in regularly. Each entry records:\n• where you are: the time, position and log reading (distance run)\n• how you move: course and speed\n• the weather: wind speed and direction, sea and weather\n• events.\nIf the electronics fail, the last logged position, course, speed and distance let you work out where you are by dead reckoning.'
],['Compute the time for 3 nautical miles at 4 knots before checking the answer.','Describe one reason the actual arrival time might differ.'], 'Mixing minutes and hours or ignoring current and changing boat speed.',[
 q('At 4 knots, how long is a 3-nautical-mile leg without current?',['30 minutes','45 minutes','75 minutes'],1,'3 ÷ 4 hours = 0.75 hour = 45 minutes.'),
 q('What checks an estimated position?',['Assuming the log cannot be wrong','Rounding the number more precisely','An independent position observation or fix'],2,'An estimate needs verification and an allowance for uncertainty.')]);
lesson('navigation','Sail a short passage',[
 'Break a route into legs, the straight stretches between turning points, each with a target, hazards and a plan for the next turn. Look around before turning at a mark, because boats often gather there.',
 'This exercise runs from south of buoy 1 to buoy 1, then buoy 2. The wind makes both direct legs sailable, but you still need to turn and retrim.',
 'Keep at least 3 metres of modeled water depth, because the keel reaches well below the surface and needs a margin. If you run aground, the attempt fails and you start again; passing the marks alone is not enough.'
],['Study both legs before setting off.','At buoy 1, look toward buoy 2 and prepare the course change.'], 'Reaching a waypoint without planning what happens immediately afterward.',[
 q('When should the next leg be considered?',['Only after leaving the chart behind','Before arriving at the turning point','Never; the yacht follows marks automatically'],1,'Anticipation leaves time for lookout, crew preparation, and safe course changes.'),
 q('You passed the marks but ran aground. Was the passage successful?',['No; avoiding hazards is part of the task','Yes; only the marks matter','Yes, if the speed was high'],0,'A completed route is not a safe route if essential margins were lost.')],{setup:{x:25,z:-15,heading:60,speed:3,trim:26},steps:[step('Pass within 35 m of buoy 1','waypoint',{x:90,z:-140,radius:35}),step('Pass within 35 m of buoy 2','waypoint',{x:240,z:-290,radius:35})],debrief:'You planned and sailed two connected legs. Tides, traffic, and real pilotage require additional training.'});
lesson('seamanship','Keep an effective lookout',[
 'A proper lookout uses your eyes, your ears and aids such as radar, AIS (ship tracking) and the radio. The collision rules call this “all available means”. Scan all round, because sails and cabin can hide other boats.',
 'Why a steady bearing means danger: two boats on straight courses that will meet stay at the same angle to each other all the way to the meeting point. So if another vessel stays on the same compass bearing, or stays lined up with the same part of your boat, while it gets closer, you are on a collision course. Check early and repeatedly, and act rather than wait for certainty.',
 'Electronic aids support the lookout; they do not replace it. In the app the other yachts do not move, so it cannot test how well you spot real traffic.'
],['Use the camera to scan the side hidden by the headsail.','Explain how you would share lookout duties with a real crew.'], 'Looking only ahead or only at the chartplotter.',[
 q('A nearby vessel stays at a nearly constant bearing while the distance closes. What might that indicate?',['No risk because it is not changing direction on the window','Potential collision risk','A guarantee that it will pass astern'],1,'Constant bearing with decreasing range is a classic warning; act early based on the full situation.'),
 q('Can a chartplotter replace sight and hearing?',['Yes','Only in daylight','No'],2,'Use all appropriate available means and keep an outside lookout.')]);
lesson('seamanship','Reason through encounters',[
 'The rules decide in advance who turns away (gives way) and who holds course (stands on), so two boats do not both turn the same way. For two sailing vessels: on different tacks, the port-tack boat (wind coming over its left, port, side) keeps clear; on the same tack, the windward boat keeps clear, because it can usually bear away more easily. Lesson {lesson:sail-46} covers this in full.',
 'An overtaking vessel keeps clear, because the boat ahead may not see it. In a narrow channel, a sailing boat must not block a ship that can only navigate safely inside it; in a traffic lane, it must not block power-driven ships following the lane. Fog, special vessels and local rules can also change who keeps clear. Do not reduce the rules to “sail always wins.”',
 'A stand-on vessel still has responsibilities and must act when needed to avoid collision. If the give-way boat is clearly not keeping clear, the stand-on boat may act on its own; if a collision can no longer be avoided by the give-way boat alone, it must act (Rule 17). A power-driven vessel doing this should, if it can, avoid turning to port for a vessel on its own port side. Learn the full collision rules and local requirements before sailing.'
],['Identify the windward side of each vessel before deciding its tack.','State the assumptions before applying a simplified crossing rule.'], 'Treating stand-on status as permission to ignore developing collision risk.',[
 q('In a basic two-sailing-vessel encounter on different tacks, which normally keeps clear?',['The starboard-tack yacht','Whichever yacht is larger','The port-tack yacht'],2,'Under the basic sailing-vessel rule, port tack keeps clear of starboard tack, subject to the full situation and other applicable rules.'),
 q('Does a stand-on vessel have no further responsibility?',['No; it must continue monitoring and act as required to avoid collision','Yes; it can close its eyes','Yes; the other vessel accepts all responsibility'],0,'Collision avoidance is an ongoing duty. The complete rules specify stand-on actions and responsibilities.')]);
lesson('seamanship','Lights, marks, and signals',[
 'Navigation lights show a vessel’s direction and what it is doing. Red is on the port side, green on starboard and white at the stern. See both red and green, and the vessel is heading straight at you, so act now: you may be on a collision course. Red only, you see its port side; green only, its starboard side; white only, you are looking at its stern.',
 'When power-driven vessels can see each other, short horn blasts tell others how they are manoeuvring; these are the international manoeuvring signals. One short blast means “I am turning to starboard”, two mean “I am turning to port”, and three mean “I am running my engine astern (in reverse)”, which does not always mean the boat is already moving backwards. Fog signals are a different system; local or inland rules may differ.',
 'Lesson {lesson:sail-50} covers the full lights, shapes and sound signals. Rules can differ in inland or local waters, so check the rules for where you sail before night or restricted-visibility operation.'
],['Identify the red port light and green starboard light on the yacht.','Distinguish an action signal from a signal used in restricted visibility.'], 'Assuming one memorized signal applies in every jurisdiction and situation.',[
 q('Which side normally carries the red sidelight?',['Starboard','Port','Both sides'],1,'The port sidelight is red; starboard is green.'),
 q('In the stated international maneuvering-signal context, two short blasts indicate…',['Turning to port','Turning to starboard','A complete fog-signal vocabulary'],0,'Two short blasts from a boat in sight mean “I am turning to port”. Check the rules where you sail before relying on it elsewhere.')]);
lesson('seamanship','Make a passage decision',[
 'A passage plan answers three questions before you set off:\n• Who is going? The crew and their experience.\n• What will the weather and water do? The forecast, tides, daylight and the hazards on your route.\n• Where can we go if it goes wrong? Safe havens (nearby harbors or bays to shelter in), how you will call for help, and a latest turn-back time.',
 'Good seamanship includes changing or abandoning the plan when its assumptions fail. Do not let an arrival promise outweigh safety, because people under pressure sail on past the easy turn-back point.',
 'Here is how the plan helps you decide when conditions change. You have a novice crew, fading daylight, a forecast wind increase, and an exposed destination. A nearby sheltered alternative is available.'
],['Name the factors that make the original destination less suitable.','Choose a conservative alternative and tell the crew why.'], 'Continuing because the destination was promised before conditions changed.',[
 q('For the stated scenario, which is the sounder decision?',['Press on to preserve the schedule','Ask the least experienced crew member to decide alone','Reassess and favor the sheltered alternative or an early return'],2,'Rising exposure and shrinking margins support a conservative change of plan.'),
 q('Which makes an abort plan useful?',['Clear decision points and viable alternatives','Leaving every decision until the last minute','A promise never to change course'],0,'Specific triggers and alternatives help avoid rushed decisions under pressure.')]);
lesson('harbor','Plan a docking approach',[
 'Docking brings together wind, current, the propeller’s pull, the boat’s momentum (it keeps moving after you slow down) and crew teamwork. Before you start, put out fenders and lines, give each person a job, choose your approach and keep a way out.',
 'Approach into the wind or the current where you can: it slows you down, so you can arrive slowly while water still flows past the rudder for steering. Arrive at the slowest speed that still lets you steer, the speed you would be willing to touch the dock at. Never use a hand or foot to stop the boat.',
 'Two effects catch beginners. In reverse, the propeller pulls the stern to one side (prop walk), so the boat will not back straight at first. And at low speed the wind pushes the high bow away from the dock. Plan for both, and keep a way out. The app models prop walk (try the lab on this page) but not the wind on the hull or dock lines, so docking is taught here as planning.',
 'Most single-engine yachts have a right-hand propeller: seen from astern, it turns clockwise when going ahead. In reverse it walks the stern to port, so the bow swings to starboard; ahead, the effect is weaker and the other way. Use it rather than fight it: in a tight space, turn to starboard, because each burst astern pulls the stern to port and keeps the turn going. Check your own boat in open water, because some propellers turn the other way.',
 'Spring lines run diagonally and stop the boat moving forward or back along the dock. The bow spring runs from the bow aft to the dock, and the stern spring from the stern forward; bow and stern lines hold the boat in. Motoring gently against a spring makes the boat pivot:\n• Ahead against the bow spring: the bow is held in and the stern swings out.\n• Astern against the stern spring: the stern is held in and the bow swings out.',
 'A spring also gets you off a dock the wind is pushing you onto, where you cannot simply motor sideways away. Put a fender at the bow, motor ahead slowly on the bow spring until the stern is well out, then let go and go astern clear. Alongside another boat of the same size, lie bow to stern so the masts and spreaders cannot touch as the boats roll.',
 'In Mediterranean mooring, the stern or bow is tied to the quay and an anchor or mooring line holds the other end, so many boats fit side by side. Going in stern-to, drop the anchor well out, at right angles to the quay and as far from it as the rode (the anchor chain or rope) allows, then reverse in while paying out. Go in bow-to if the water gets shallow near the quay and could hit the rudder, or for privacy. Some marinas lay a permanent mooring line from a sinker on the seabed, sometimes called a dead anchor: take it to the bow, and when leaving, drop it and let it sink before you use the engine, or it can wrap the propeller.'
],['Describe your approach, crew jobs, and go-around plan before moving.','Explain why wind and current change a safe approach.'], 'Relying on crew to jump ashore or physically catch the yacht.',[
 q('If the approach becomes unstable, what should the preplanned option be?',['Ask someone to fend off with a foot','Abort and make a controlled new approach if safe','Add speed to get it over with'],1,'An escape plan is part of preparation; avoid trapping the boat or crew in an unrecoverable maneuver.'),
 q('Why approach a berth heading into the wind or current when you can?',['It makes the boat go faster','It stops prop walk','It slows the boat while water still flows past the rudder'],2,'The wind or current acts as a brake, so you can come in slowly and still steer. With them behind you, the boat keeps being pushed on.'),
 q('With a right-hand propeller, which way does the stern walk when you go astern?',['To port','To starboard','It stays straight'],0,'A right-hand propeller walks the stern to port in reverse, so the bow swings to starboard. In a tight space, turn to starboard to use it.')]);
lesson('harbor','Choose an anchorage',[
 'Choose shelter, holding ground the anchor can dig into (such as sand or mud), and enough depth at every state of the tide. Leave room to swing clear of hazards and other boats.',
 'An anchor holds best when it is pulled flat along the seabed, because then it digs in. With a short rode (the chain or rope between anchor and boat) the pull comes from above and lifts the anchor out. That is why you let out several times the depth: the extra length, and the weight of chain, keep the pull flat and soften jerks from waves. Use more in strong wind. Scope is rode length divided by the height from bow roller to seabed.',
 'Worked example: in 5 m of water with the bow roller 1 m above the water, a 5:1 scope gives 30 m of rode. 5:1 is a common starting point in calm weather; use more in strong wind. Also allow for the tide and check your swing room.',
 'Different anchors suit different seabeds:\n• Claw anchors, such as the Bruce, dig well into sand and mud.\n• Plough anchors, such as the Delta and CQR, also dig well into sand and mud.\n• A folding grapnel suits rock or a small boat.\n• A mushroom anchor is meant for permanent moorings in soft mud.\nChain is heavy and keeps the pull low along the bottom. If you use rope, choose one that sinks and stretches, such as nylon: it absorbs jerks and stays clear of propellers. Many yachts use chain with a rope tail.',
 'Sometimes a single anchor is not enough to hold the boat. Use two when one cannot hold in strong wind, when wind and current pull from different directions, or in a river where the current reverses. Lay them well apart, about 45° on either side of the bow in strong wind, or one ahead and one astern in a narrow river, and make sure the rodes cannot tangle as the boat swings.'
],['Sketch the expected swing circle and nearby hazards.','Include roller height in the example’s vertical distance.'], 'Multiplying charted depth alone or assuming an anchor always holds once it touches bottom.',[
 q('Under the stated example assumptions, how much rode corresponds to 5:1?',['25 m','30 m','5 m'],1,'The vertical distance is 5 + 1 = 6 m. Five times 6 m is 30 m, before other real-world considerations.'),
 q('What must an anchorage plan consider beyond depth?',['Only the distance to a café','Only anchor color','Shelter, holding ground, tide, swing room, and hazards'],2,'Depth alone does not establish a suitable or safe anchorage.'),
 q('Which rope makes a good anchor rode?',['One that sinks and stretches','One that floats','One that does not stretch at all'],0,'A sinking rope stays clear of propellers, and its stretch absorbs the jerks of a boat moving in waves.')]);
lesson('harbor','Stop, then anchor',[
 'Approach slowly, heading into the wind (or the current, whichever affects the boat more), so the boat comes to a stop on its own. Lower the anchor to the seabed once the boat has stopped. Then let the wind push the boat backward as you pay out rode, so the chain lies along the bottom instead of piling on top of the anchor.',
 'When enough rode is out, set the anchor by pulling on it gently, often with a little engine astern. Check that it holds: pick two objects ashore that line up, such as a lamp post in front of a church tower, and watch whether they stay lined up. Keep checking over time, especially when the wind changes.',
 'You can also feel whether the anchor holds by resting a hand on the rode. A steady pull means it is holding; a juddering vibration means it is dragging across the bottom, and the bow no longer stays pointed into the wind. If it drags, first let out more rode, which often lets it dig in. If it still drags, lift it and anchor again.',
 'Do not leave the anchor’s load on the windlass (the winch that lifts the chain), because it is not built to take sudden jerks. Once anchored, tie a snubber, a short rope from the chain to a bow cleat, so the cleat takes the strain and the rope absorbs jerks. A different use of the anchor: it can help you come close to a shore with the bow facing seaward. Drop it while still approaching and control the rode as it runs out, so the anchor stops the boat under control.',
 'In this exercise: lower the sails and coast below 0.8 knots (slower than walking pace) with the anchor up. Set a 45 m rode target and run the windlass; it pays out over time and stops at the target. Wait for 45 m actually paid out, the windlass stopped, and ground speed below 0.2 knots. Deploying early ends the attempt.'
],['Reduce sail power well before the intended stopping point.','Wait for speed to fall before using the anchor control.'], 'Deploying the anchor at speed instead of completing a controlled approach.',[
 q('What is the correct sequence in this exercise?',['Anchor at full speed, then lower sails','Lower sails, slow with anchor up, then anchor','Ignore the speed display'],1,'The exercise checks anticipation and sequencing, not the anchor’s holding ability.'),
 q('Why let the boat drift back while paying out rode?',['So the rode lies along the seabed instead of piling on the anchor','To make the windlass faster','So the anchor stays off the bottom'],0,'Rode piled on top of the anchor can foul it. Letting the boat fall back lays the rode out, so the pull on the anchor stays flat.'),
 q('Your hand on the anchor line feels a juddering vibration and the bow falls off the wind. What do you do first?',['Let out more rode','Motor ahead hard','Nothing; that is normal'],0,'Juddering means the anchor is dragging. More rode often lets it dig in; if it does not, lift the anchor and anchor again.')],{setup:{x:681,z:428,heading:225,speed:2,trim:34,anchorRode:45},anchorOnlyAtEnd:true,steps:[step('Lower sails and coast below 0.8 knots, anchor up','coast',.8,3),{...step('Pay out 45 m, stop the windlass, and settle below 0.2 knots','anchor',true,4),minimumRode:45}],debrief:'You practiced a controlled stop and the correct simplified sequence. Real anchor setting is not assessed.'});
lesson('harbor','Prepare to leave',[
 'Before departure, recheck everything, because things change while you are anchored. A new boat may lie close by, or the wind may shift. Check the route, conditions and crew, secure lines and equipment, and tell everyone what happens next.',
 'To lift the anchor, bring the boat to it rather than pulling the boat with the rode. Motor or sail slowly toward the anchor while the crew brings in the slack. When the rode is straight up and down, the pull is vertical and the anchor breaks out of the seabed easily. The windlass lifts the rode; it is not for towing the boat.',
 'Once the anchor leaves the bottom you are drifting, so get steerage (enough speed for the rudder to work) quickly by engine or sail. Now try it in the app: the bow starts above the anchor. Select Weigh anchor and wait until it is fully stowed, then raise the sails and settle on a steady reach. If the rode goes tight, retrieval pauses.'
],['Confirm the wind and your intended course before releasing the hold.','Restore sail power, gain steerage, and make a controlled departure.'], 'Releasing the boat before having a clear plan and adequate room.',[
 q('What belongs before releasing the boat?',['Crew briefing, lookout, and a clear plan','A maximum-speed test','Looking at the route only after leaving'],0,'Preparation should precede the point at which the vessel is free to move.'),
 q('When does an anchor break out of the seabed most easily?',['When the rode is pulled flat along the bottom','When the rode is straight up and down above it','When the boat moves away fast'],1,'A vertical pull lifts the anchor’s point out. A flat pull is what makes it dig in, which is why you bring the boat over the anchor first.')],{setup:{x:649.667,z:459.333,heading:225,sails:0,anchor:true,anchorRode:45},steps:[step('Weigh anchor','anchor',false,1),step('Raise sails','sails',1,1),step('Maintain a reach above 2.5 knots','speedAbove',2.5,8)],debrief:'You restored movement deliberately and established control in a prepared practice area.'});
lesson('readiness','Person overboard priorities',[
 'When someone falls overboard, act at once, sharing the jobs:\n• Shout “person overboard!”\n• Throw a lifebuoy and a marker (a buoy with a flag or light) straight away.\n• Point at them nonstop: a head in waves vanishes within seconds.\n• Call for help and give everyone a job.',
 'Then bring the boat back under control and return. Stay close: many recoveries fail because the boat gets too far away and loses sight of the person. Plan the final approach on a close reach (wind just forward of the side), so you can slow down by easing the sails or speed up by trimming, and stop beside the person. Keep the propeller in neutral or stopped near them.',
 'A lifebuoy light switches itself on when the buoy floats upright in the water, so throw the buoy with its light attached; do not wait to test it. In strong wind and big waves, a return under sail can be hard to control. Once the buoy is thrown and someone is pointing:\n• Roll away the headsail.\n• Check that no lines are in the water, because a rope can wrap the propeller.\n• Start the engine and approach slowly, with the propeller stopped near the person.',
 'Lifting a person aboard is often the hardest part: a wet adult is heavy and the side of the boat is high. Know your boat’s method, such as a sling, a halyard on a winch or a ladder, before you need it. This app has no person-overboard model, so this lesson checks priorities; practice the maneuver with an instructor and a training object.'
],['Assign a dedicated pointer who does not lose sight of the casualty.','Explain why returning alongside is only one part of recovery.'], 'Everyone looking at the controls while nobody keeps the casualty in sight.',[
 q('What is an immediate priority after the alarm?',['Everyone changes the chart scale','Keep visual contact and deploy appropriate flotation/marking aids','Wait to see whether the person swims back'],1,'Tracking and supporting the casualty are urgent while the crew organizes the recovery and help.'),
 q('Does reaching the casualty complete the task?',['Yes','Only in daylight','No; safe stopping, lifting aboard, and aftercare also matter'],2,'Recovery includes the difficult physical steps and casualty care, not just navigation.')]);
lesson('readiness','Distress and urgent action',[
 'Distress means grave and imminent danger to life: people need help now. Know the boat’s radio and other communications, the local procedures, and how to give a rescuer four things: who you are, where you are, what is wrong and what help you need.',
 'For an immediate danger to life, use the distress equipment you have. That may be a DSC distress alert (a button on the VHF radio that sends an automatic alert with your position) and a MAYDAY call on VHF channel 16. Learn the equipment before you leave, and never send a real distress alert for practice.',
 'Any one of these signals means a vessel needs immediate help:\n• A red hand flare or a red parachute rocket.\n• Orange smoke.\n• Flames on the vessel.\n• The code flags N over C, or a square flag with a ball above or below it.\n• A person slowly and repeatedly raising and lowering outstretched arms.\nUse them only in real distress, and know where your own flares are and how they fire.',
 'Distress can also be heard, or received by radio:\n• A gun or other explosion about once a minute.\n• A continuous sound on a horn or fog signal.\n• SOS in any signalling method (three short, three long, three short).\n• MAYDAY by radio, a DSC distress alert, or an emergency beacon (EPIRB or PLB).\nA single code flag on its own is not a distress signal, and other horn patterns, such as six short, three long, six short, mean nothing.',
 'Receiving a distress call obliges you to go and help. Go as fast as you can, unless that would put your own vessel and crew in serious danger, and tell the rescue service what you are doing. Distress means a risk to life. A boat that only wants a tow, with nobody in danger, is not in distress: you may help if your boat, fuel, lines and crew make it safe, but you are not obliged to.',
 'After a grounding, flooding or fire, protect people first. Then work out what has happened, call for help if you need it and follow the boat’s own emergency procedures. Driving hard with the engine after running aground can make the damage worse.',
 'After running aground, first put the engine in neutral. Driving ahead pushes the keel further in and can suck sand into the engine’s cooling water. Check that everyone is unhurt, then check the hull and bilge for water. If the boat is sound, try to come off the way you came: lower or ease the sails so they stop pushing you on, and use reverse gently. If that fails, wait for help or a rising tide rather than forcing it.',
 'When you find water aboard, act at once: start the pumps, then find where the water comes in. Tasting it helps: fresh water points to a tank or pipe, salt water to a hull fitting, hose or damage. Close the seacocks you can reach, and plug or cover the opening with a bung, cloth or cushion held in place. If the pumps cannot keep up, the engine’s sea-water cooling pump can also pump the bilge, on boats fitted to switch its intake. If the water keeps rising, call for help early.',
 'A fire needs fuel, air and heat, so take away any one of them. Turn the boat so the wind carries smoke and flames away from the crew and the rest of the boat; with a fire forward, put the stern to the wind, and with a fire aft, the bow. For an engine fire, stop the engine, shut off the fuel, and discharge the extinguisher through a small opening rather than opening the hatch wide, which feeds the fire with air. Get gas bottles near the fire overboard first.'
],['Rehearse the information you would provide without transmitting.','Locate the simulated position and explain what a real rescue service needs.'], 'Giving a long story but omitting position, identity, or the kind of help needed.',[
 q('Which information is central to a distress message?',['Only the yacht’s paint color','Identity, position, danger, and assistance needed','A complete holiday itinerary'],1,'Clear essential information helps rescuers locate the vessel and prioritize a response.'),
 q('How should you practice an emergency radio message?',['Make a real distress transmission for realism','Trigger DSC distress without warning','Rehearse without transmitting, or use an authorized training setting'],2,'False distress alerts can divert real emergency resources.'),
 q('Which of these is a distress signal?',['A square flag with a ball above it','A single international code flag','Five short horn blasts'],0,'A square flag with a ball above or below it is a distress signal. A single code flag is not, and five short blasts mean doubt about another vessel’s intentions.'),
 q('Your motorboat runs onto a sandbank. What do you do first?',['Put the engine in neutral','Apply full power ahead','Jump over the side to push'],0,'Driving ahead pushes you further on and can suck sand into the cooling water. Stop, check people and the hull, then try to back off gently.')]);
lesson('readiness','Your assessed first passage',[
 'Combine the course skills without rushing, one stage at a time:\n• Steer a steady course.\n• Trim the sails well.\n• Tack, then recover control.\n• Slow to a planned stop.',
 'The simulator gives measured targets but no automatic steering. Each stage must be completed in order. Grounding or using the anchor before the final stopping stage invalidates the attempt, because the test checks your order of work, as at sea.',
 'The final stage anchors in deep water, so the target is 180 m of rode. That is far more than the 45 m earlier, because deeper water needs more rode (Lesson {lesson:sail-30}). Wait for all 180 m to be paid out, the windlass to stop, and ground speed to fall below 0.2 knots. Allow about 15 minutes for the complete exercise.',
],['Brief yourself on the sequence before selecting Begin practice.','Use the checklist and retain lookout while monitoring the instruments.'], 'Treating isolated skills as independent of lookout, sea room, and the next step.',[
 q('Which result counts as a successful simulated passage?',['High speed alone','Completing the stages in order while keeping the safety margins','Touching every control once'],1,'The assessment combines controlled performance, sequence, and maintained margins.'),
 q('If a task is invalidated, what is the right response?',['Restart, understand the cause, and practice again','Ignore the warning and claim a pass','Change the weather until the result is accepted'],0,'Reviewing the cause is part of learning; invalid attempts do not earn a pass.')],{setup:{x:100,z:220,heading:60,speed:3,trim:70,anchorRode:180},anchorOnlyAtEnd:true,steps:[step('Hold 045° ±5° above 2 knots','heading',45,10),step('Maintain efficient trim','trim',6,10),step('Tack through the bow and recover speed','tack',null,6,'From 045°, turn port through 315° and settle near 265°.'),step('Lower sails and coast below 0.8 knots','coast',.8,3),{...step('Pay out 180 m, stop the windlass, and settle below 0.2 knots','anchor',true,4),minimumRode:180}],debrief:'You linked steering, trimming, tacking, and stopping. Review any hints used and repeat with less assistance.'});
lesson('readiness','From simulation to the sea',[
 'Knowing, simulating and doing on a real boat are three different things. Explaining a task, doing it in this model and doing it aboard a real yacht each test something else. Your course record separates theory checks from simulated practice and records the use of hints.',
 'The next step is supervised training on the water, covering:\n• preparation and equipment checks\n• knots and line handling\n• hoisting, trimming and reefing\n• tacking and gybing with crew\n• engine handling and docking\n• real anchoring\n• lookout and navigation\n• person-overboard recovery',
 'Choose an instructor and conditions appropriate to your experience. Bring your course record, explain the simulator’s limitations, and ask for an individual practical assessment. Course completion here is a learning milestone, not a license or safety certification.'
],['Review your record and identify the exercises where you used hints or repeated attempts.','Write down three real-world skills that still need supervised practice.'], 'Treating a completion badge as evidence that every real boat and condition can be handled safely.',[
 q('What should follow successful completion?',['Supervised on-water training and practical assessment','Immediate solo sailing in unfamiliar conditions','Assuming docking and rescue were already mastered'],0,'The course supports preparation; it does not replace real experience and instruction.'),
 q('Which important skills remain unassessed by this simulator?',['Reading the modeled heading','Loaded line handling, engine docking, and casualty recovery','Changing the camera'],1,'Those skills require forces, equipment, coordination, and conditions that this version does not model.')]);
